 if blocks:
  cols=[]
  for m,cells in blocks:
   v=sp.Matrix([scalar(c) for c in cells]);syms=sorted(v.free_symbols,key=str)
   cols.extend([v.diff(s) for s in syms] if syms else [v])
  B=sp.Matrix.hstack(*cols);assert B.rows==n
  u=B.rank();r=n-u
